import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  input,
  output,
  viewChild,
} from '@angular/core';

@Component({
  selector: 'omm-bottom-sheet',
  imports: [],
  templateUrl: './bottom-sheet.html',
  styleUrl: './bottom-sheet.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BottomSheet {
  ariaLabel = input<string>();
  /**
   * On a wide viewport, show a centred panel instead of a sheet along the
   * bottom edge. A full-width strip suits a phone held in one hand; on a
   * desktop window it stretches short content across the whole screen.
   */
  panelOnWide = input(false, { transform: booleanAttribute });
  closed = output<void>();

  private dlg = viewChild.required<ElementRef<HTMLDialogElement>>('dlg');

  open(): void {
    this.dlg().nativeElement.showModal();
  }

  close(): void {
    this.dlg().nativeElement.close();
  }

  protected onClose() {
    this.closed.emit();
  }

  protected onBackdropClick(e: MouseEvent) {
    if (e.target === this.dlg().nativeElement) this.close();
  }
}
